export const gearRadius=o=>Math.min(o.w,o.h)/2;
export function hitObject(o,p){if(o.type==='gear'){const radius=gearRadius(o);return Math.hypot(p.x-o.x-o.w/2,p.y-o.y-o.h/2)<=radius}const radians=-(o.rotation||0)*Math.PI/180,cx=o.x+o.w/2,cy=o.y+o.h/2,dx=p.x-cx,dy=p.y-cy,lx=dx*Math.cos(radians)-dy*Math.sin(radians)+o.w/2,ly=dx*Math.sin(radians)+dy*Math.cos(radians)+o.h/2;return lx>=0&&lx<=o.w&&ly>=0&&ly<=o.h}
export function gearsTouch(a,b){const radiusA=gearRadius(a),radiusB=gearRadius(b),distance=Math.hypot(a.x+a.w/2-b.x-b.w/2,a.y+a.h/2-b.y-b.h/2);return Math.abs(distance-radiusA-radiusB)<=Math.max(8,Math.min(radiusA,radiusB)*.15)&&distance>Math.abs(radiusA-radiusB)+5}
export function spinGear(objects,driver,delta){const pending=[[driver,delta]],visited=new Set();while(pending.length){const[o,amount]=pending.shift();if(visited.has(o.id))continue;visited.add(o.id);o.turnAngle=(Number.isFinite(o.turnAngle)?o.turnAngle:Number(o.rotation)||0)+amount;o.rotation=o.turnAngle%360;for(const other of objects){if(other.type!=='gear'||visited.has(other.id)||!gearsTouch(o,other))continue;pending.push([other,-amount*gearRadius(o)/gearRadius(other)])}}return visited}
export function angleDelta(current,previous){return Math.atan2(Math.sin(current-previous),Math.cos(current-previous))}

export function updateAttachments(objects,pointer){const done=new Set(),visiting=new Set();function place(o){if(done.has(o.id)||visiting.has(o.id))return;visiting.add(o.id);for(const event of o.events||[]){if(event.action!=='attach'||event.condition!=='frame')continue;const parent=objects.find(p=>p.id===event.targetId);if(!parent||parent===o)continue;place(parent);o.x=parent.x+parent.w/2+(event.offsetX||0)-o.w/2;o.y=parent.y+parent.h/2+(event.offsetY||0)-o.h/2}visiting.delete(o.id);done.add(o.id)}for(const o of objects)place(o);if(pointer)for(const o of objects)for(const event of o.events||[]){if(event.action==='facepointer'&&event.condition==='frame')o.rotation=Math.atan2(pointer.y-o.y-o.h/2,pointer.x-o.x-o.w/2)*180/Math.PI+(event.value||0)}}
